package app.dayflow;
import android.content.*;
import android.graphics.*;
import android.os.Build;
import com.google.android.material.color.*;
import com.google.android.material.color.utilities.Hct;

final class ThemeColors {
 static String source(Context c){SharedPreferences p=c.getSharedPreferences("settings",0);return p.getString("color_source",new java.io.File(c.getFilesDir(),"wallpaper.jpg").isFile()?"wallpaper":"system");}
 static void extract(Context c,Bitmap bitmap){Bitmap sample=Bitmap.createScaledBitmap(bitmap,96,96,true);try{Integer seed=new DynamicColorsOptions.Builder().setContentBasedSource(sample).build().getContentBasedSeedColor();if(seed!=null)c.getSharedPreferences("settings",0).edit().putInt("wallpaper_seed",seed).apply();}finally{if(sample!=bitmap)sample.recycle();}}
 static void apply(MainActivity a){SharedPreferences p=a.getSharedPreferences("settings",0);if(!p.getBoolean("dynamic_color",true)||Build.VERSION.SDK_INT<31)return;String source=source(a);if(source.equals("wallpaper")&&!p.contains("wallpaper_seed")){java.io.File wallpaper=new java.io.File(a.getFilesDir(),"wallpaper.jpg");if(wallpaper.isFile()){BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=16;Bitmap image=BitmapFactory.decodeFile(wallpaper.getPath(),options);if(image!=null)try{extract(a,image);}finally{image.recycle();}}}DynamicColorsOptions.Builder builder=new DynamicColorsOptions.Builder();if(source.equals("wallpaper")&&p.contains("wallpaper_seed"))builder.setContentBasedSource(p.getInt("wallpaper_seed",0xff386a5c));else if(source.equals("custom"))builder.setContentBasedSource(p.getInt("custom_seed",0xff386a5c));DynamicColors.applyToActivityIfAvailable(a,builder.build());}
 static int accent(Context c,boolean dark){SharedPreferences p=c.getSharedPreferences("settings",0);if(p.getBoolean("dynamic_color",true)){String source=source(c);if(source.equals("wallpaper")&&p.contains("wallpaper_seed")||source.equals("custom")){int seed=p.getInt(source.equals("custom")?"custom_seed":"wallpaper_seed",0xff386a5c);Hct color=Hct.fromInt(seed);return Hct.from(color.getHue(),color.getChroma(),dark?80:40).toInt();}if(Build.VERSION.SDK_INT>=31)return c.getColor(dark?android.R.color.system_accent1_200:android.R.color.system_accent1_700);}return dark?0xffa0d0bf:0xff386a5c;}
 static void settings(MainActivity a,android.widget.LinearLayout page){SharedPreferences p=a.prefs;android.widget.Spinner source=TaskTypes.spinner(a,page,"强调色来源",java.util.Arrays.asList("系统壁纸","应用内壁纸","自定义颜色"));source.setSelection(source(a).equals("wallpaper")?1:source(a).equals("custom")?2:0);com.google.android.material.textfield.TextInputEditText seed=Ui.field(a,page,"自定义颜色（#RRGGBB）",String.format(java.util.Locale.ROOT,"#%06X",p.getInt("custom_seed",0xff386a5c)&0xffffff),false);page.addView(Ui.help(a,"Android12+使用Material调色板，并适配深浅主题；应用内壁纸取色不依赖手机系统壁纸。"));page.addView(Ui.button(a,"应用配色",false,()->{try{String value=new String[]{"system","wallpaper","custom"}[source.getSelectedItemPosition()];if(value.equals("custom")&&!seed.getText().toString().matches("#[0-9a-fA-F]{6}"))throw new Exception("请填写#RRGGBB颜色");if(value.equals("wallpaper")){java.io.File file=new java.io.File(a.getFilesDir(),"wallpaper.jpg");if(!file.isFile())throw new Exception("请先选择应用壁纸");BitmapFactory.Options options=new BitmapFactory.Options();options.inSampleSize=16;Bitmap bitmap=BitmapFactory.decodeFile(file.getPath(),options);if(bitmap==null)throw new Exception("无法读取壁纸");try{extract(a,bitmap);}finally{bitmap.recycle();}}p.edit().putString("color_source",value).putBoolean("dynamic_color",true).putInt("custom_seed",Color.parseColor(seed.getText().toString())).apply();AgendaWidget.refresh(a);a.recreate();}catch(Exception e){a.message(e.getMessage());}}));}
}
